import { useState, useRef, useEffect } from 'react';
import { verifyBulk, pollJob, exportUrl } from '../api';

const PREVIEW_LIMIT = 20;

const CATEGORIES = [
  { key: 'delivers', label: '✅ Delivers',    color: 'var(--green)', bg: 'var(--green-bg)', border: 'var(--green-border)', filter: r => r.category === 'delivers' },
  { key: 'unknown',  label: '⚠️ Unconfirmed', color: 'var(--amber)', bg: 'var(--amber-bg)', border: 'var(--amber-border)', filter: r => r.category === 'unknown'  },
  { key: 'bounce',   label: '❌ Bounce',       color: 'var(--red)',   bg: 'var(--red-bg)',   border: 'var(--red-border)',   filter: r => r.category === 'bounce'   },
  { key: 'all',      label: 'All',            color: 'var(--text)',  bg: 'var(--bg3)',      border: 'var(--border)',       filter: () => true },
];

function RiskBadge({ risk }) {
  const cls = { LOW: 'badge-low', MEDIUM: 'badge-medium', HIGH: 'badge-high' }[risk] || 'badge-null';
  return <span className={`badge ${cls}`}>{risk}</span>;
}

function SmtpBadge({ val }) {
  if (val === true)  return <span className="badge badge-valid">250 OK</span>;
  if (val === false) return <span className="badge badge-invalid">Rejected</span>;
  return <span className="badge badge-null">Timeout</span>;
}

function ResultsPanel({ results, jobId, onReset }) {
  const [activeTab, setActiveTab] = useState('delivers');

  const cat = CATEGORIES.find(c => c.key === activeTab);
  const filtered = results.filter(cat.filter);
  const preview  = filtered.slice(0, PREVIEW_LIMIT);
  const remaining = filtered.length - preview.length;

  // Count per category
  const counts = {};
  CATEGORIES.forEach(c => { counts[c.key] = results.filter(c.filter).length; });

  return (
    <div className="animate-in">
      <div style={{ marginBottom: 24 }}>
        <h2 style={{ fontSize: 18, fontWeight: 700, marginBottom: 4, letterSpacing: '-0.02em' }}>Verification complete</h2>
        <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>{results.length.toLocaleString()} emails processed</p>
      </div>

      {/* Summary stat cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10, marginBottom: 24 }}>
        {CATEGORIES.filter(c => c.key !== 'all').map(c => (
          <div
            key={c.key}
            onClick={() => setActiveTab(c.key)}
            style={{
              background: activeTab === c.key ? c.bg : 'var(--bg2)',
              border: `1.5px solid ${activeTab === c.key ? c.border : 'var(--border)'}`,
              borderRadius: 'var(--radius-lg)', padding: '14px 16px',
              cursor: 'pointer', transition: 'all 0.15s',
              boxShadow: activeTab === c.key ? 'var(--shadow-md)' : 'var(--shadow)',
            }}
          >
            <div style={{ fontFamily: 'Syne', fontSize: 22, fontWeight: 700, color: activeTab === c.key ? c.color : 'var(--text)', letterSpacing: '-0.02em' }}>
              {counts[c.key].toLocaleString()}
            </div>
            <div style={{ fontSize: 12, color: activeTab === c.key ? c.color : 'var(--text-muted)', marginTop: 2 }}>{c.label}</div>
          </div>
        ))}
      </div>

      {/* Category tabs */}
      <div style={{ display: 'flex', gap: 2, background: 'var(--bg3)', border: '1.5px solid var(--border)', borderRadius: 'var(--radius)', padding: 3, marginBottom: 16, width: '100%', overflowX: 'auto' }}>
        {CATEGORIES.map(c => (
          <button
            key={c.key}
            onClick={() => setActiveTab(c.key)}
            style={{
              flex: 1, background: activeTab === c.key ? 'var(--bg2)' : 'transparent',
              color: activeTab === c.key ? c.color : 'var(--text-muted)',
              border: activeTab === c.key ? `1.5px solid ${c.border}` : '1.5px solid transparent',
              padding: '7px 10px', borderRadius: 7,
              fontFamily: 'Syne', fontWeight: 600, fontSize: 12,
              transition: 'all 0.15s', whiteSpace: 'nowrap',
              boxShadow: activeTab === c.key ? 'var(--shadow)' : 'none',
            }}
          >
            {c.label} ({counts[c.key].toLocaleString()})
          </button>
        ))}
      </div>

      {/* Table */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px 0', color: 'var(--text-dim)', fontSize: 13 }}>
          No emails in this category
        </div>
      ) : (
        <div style={{ background: 'var(--bg2)', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-lg)', overflow: 'hidden', boxShadow: 'var(--shadow)' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead>
              <tr style={{ background: 'var(--bg3)', borderBottom: '1.5px solid var(--border)' }}>
                <th style={{ padding: '10px 16px', textAlign: 'left', fontFamily: 'Syne', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>Email</th>
                <th style={{ padding: '10px 16px', textAlign: 'left', fontFamily: 'Syne', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>SMTP</th>
                <th style={{ padding: '10px 16px', textAlign: 'left', fontFamily: 'Syne', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>Risk</th>
                <th style={{ padding: '10px 16px', textAlign: 'left', fontFamily: 'Syne', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>Flags</th>
              </tr>
            </thead>
            <tbody>
              {preview.map((r, i) => (
                <tr key={i} style={{ borderBottom: i < preview.length - 1 ? '1px solid var(--border)' : 'none' }}>
                  <td style={{ padding: '11px 16px', fontFamily: 'DM Mono', fontSize: 12, color: 'var(--text)' }}>{r.email}</td>
                  <td style={{ padding: '11px 16px' }}><SmtpBadge val={r.smtp_valid} /></td>
                  <td style={{ padding: '11px 16px' }}><RiskBadge risk={r.risk} /></td>
                  <td style={{ padding: '11px 16px' }}>
                    <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                      {r.catch_all   && <span style={{ fontSize: 10, background: '#f5f3ff', color: '#7c3aed', border: '1px solid #ddd6fe', borderRadius: 4, padding: '2px 6px', fontFamily: 'DM Mono' }}>catch-all</span>}
                      {r.disposable  && <span style={{ fontSize: 10, background: 'var(--red-bg)', color: 'var(--red)', border: '1px solid var(--red-border)', borderRadius: 4, padding: '2px 6px', fontFamily: 'DM Mono' }}>disposable</span>}
                      {r.role_based  && <span style={{ fontSize: 10, background: 'var(--amber-bg)', color: 'var(--amber)', border: '1px solid var(--amber-border)', borderRadius: 4, padding: '2px 6px', fontFamily: 'DM Mono' }}>role-based</span>}
                      {!r.catch_all && !r.disposable && !r.role_based && <span style={{ fontSize: 11, color: 'var(--text-dim)' }}>—</span>}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* More rows notice + download */}
          {remaining > 0 && (
            <div style={{ padding: '14px 16px', borderTop: '1px solid var(--border)', background: 'var(--bg3)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: 12, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>
                Showing {PREVIEW_LIMIT} of {filtered.length.toLocaleString()} — {remaining.toLocaleString()} more not shown
              </span>
              <a href={exportUrl(jobId, activeTab)} download style={{ textDecoration: 'none' }}>
                <button className="btn-export" style={{ fontSize: 12 }}>
                  ↓ Download all {filtered.length.toLocaleString()} {cat.label.toLowerCase()}
                </button>
              </a>
            </div>
          )}
        </div>
      )}

      {/* Download row */}
      <div style={{ marginTop: 20, display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
        <span style={{ fontSize: 12, color: 'var(--text-dim)', fontFamily: 'DM Mono', marginRight: 4 }}>Download:</span>
        {CATEGORIES.map(cat => (
          <a key={cat.key} href={exportUrl(jobId, cat.key)} download style={{ textDecoration: 'none' }}>
            <button className="btn-export">↓ {cat.label} ({counts[cat.key].toLocaleString()})</button>
          </a>
        ))}
      </div>

      <button className="btn-ghost" onClick={onReset} style={{ marginTop: 16 }}>← Verify another list</button>
    </div>
  );
}

export default function BulkVerify() {
  const [mode, setMode] = useState('upload');
  const [dragging, setDragging] = useState(false);
  const [file, setFile] = useState(null);
  const [pasteText, setPasteText] = useState('');
  const [uploading, setUploading] = useState(false);
  const [job, setJob] = useState(null);
  const [error, setError] = useState('');
  const fileRef = useRef();
  const pollRef = useRef();

  const handleFile = (f) => {
    if (!f || !f.name.endsWith('.csv')) { setError('Only .csv files accepted'); return; }
    setFile(f); setError('');
  };

  const handleDrop = (e) => {
    e.preventDefault(); setDragging(false);
    handleFile(e.dataTransfer.files[0]);
  };

  const pasteToFile = () => {
    const lines = pasteText.split(/[\n,;]+/).map(e => e.trim().toLowerCase()).filter(e => e.includes('@'));
    if (lines.length === 0) { setError('No valid email addresses found'); return null; }
    const csv = 'email\n' + lines.join('\n');
    return new File([csv], 'pasted_emails.csv', { type: 'text/csv' });
  };

  const handleStart = async () => {
    setUploading(true); setError(''); setJob(null);
    try {
      let uploadFile = mode === 'paste' ? pasteToFile() : file;
      if (!uploadFile) { setUploading(false); return; }
      const data = await verifyBulk(uploadFile);
      setJob({ id: data.job_id, total: data.total, progress: 0, status: 'processing', results: [] });
    } catch (e) {
      setError(e.message || 'Upload failed. Make sure the backend is running.');
      setUploading(false);
    }
  };

  useEffect(() => {
    if (!job || job.status === 'done') { setUploading(false); return; }
    pollRef.current = setInterval(async () => {
      try {
        const data = await pollJob(job.id);
        setJob(prev => ({ ...prev, ...data }));
        if (data.status === 'done') { clearInterval(pollRef.current); setUploading(false); }
      } catch {}
    }, 1500);
    return () => clearInterval(pollRef.current);
  }, [job?.id, job?.status]);

  const reset = () => { setFile(null); setJob(null); setError(''); setUploading(false); setPasteText(''); };

  const emailCount = mode === 'paste' ? pasteText.split(/[\n,;]+/).filter(e => e.trim().includes('@')).length : null;
  const pct = job ? Math.min(Math.round((job.progress / (job.total || 1)) * 100), 100) : 0;
  const canStart = mode === 'upload' ? !!file : pasteText.trim().length > 0;

  // Show results panel once done
  if (job?.status === 'done' && job.results?.length > 0) {
    return <ResultsPanel results={job.results} jobId={job.id} onReset={reset} />;
  }

  // Show progress
  if (job) {
    return (
      <div className="animate-in">
        <div style={{ marginBottom: 24 }}>
          <h2 style={{ fontSize: 18, fontWeight: 700, marginBottom: 6, letterSpacing: '-0.02em' }}>Verifying your list...</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>{job.progress?.toLocaleString() || 0} of {job.total?.toLocaleString()} emails checked</p>
        </div>
        <div style={{ background: 'var(--bg3)', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '24px 28px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 14 }}>
            <div style={{ fontFamily: 'DM Mono', fontSize: 13, color: 'var(--text-muted)' }}>Processing...</div>
            <div style={{ fontFamily: 'Syne', fontSize: 32, fontWeight: 700, letterSpacing: '-0.04em', lineHeight: 1 }}>{pct}%</div>
          </div>
          <div style={{ height: 8, background: 'var(--bg4)', borderRadius: 99, overflow: 'hidden' }}>
            <div style={{ height: '100%', width: `${pct}%`, background: 'var(--accent)', borderRadius: 99, transition: 'width 0.5s ease' }} />
          </div>
        </div>
      </div>
    );
  }

  // Upload / paste form
  return (
    <div>
      <div style={{ marginBottom: 24 }}>
        <h2 style={{ fontSize: 18, fontWeight: 700, marginBottom: 6, letterSpacing: '-0.02em' }}>Bulk verify</h2>
        <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>Upload a CSV or paste emails directly. Up to 50,000 per job.</p>
      </div>

      <div style={{ display: 'flex', gap: 0, background: 'var(--bg3)', border: '1.5px solid var(--border)', borderRadius: 'var(--radius)', padding: 3, width: 'fit-content', marginBottom: 24 }}>
        {[{ id: 'upload', label: '⬆ Upload CSV' }, { id: 'paste', label: '📋 Paste emails' }].map(m => (
          <button key={m.id} onClick={() => { setMode(m.id); setError(''); }}
            style={{
              background: mode === m.id ? 'var(--bg2)' : 'transparent',
              color: mode === m.id ? 'var(--text)' : 'var(--text-muted)',
              border: mode === m.id ? '1.5px solid var(--border)' : '1.5px solid transparent',
              padding: '8px 18px', borderRadius: 8,
              fontFamily: 'Syne', fontWeight: 600, fontSize: 12,
              transition: 'all 0.15s',
              boxShadow: mode === m.id ? 'var(--shadow)' : 'none',
            }}>{m.label}</button>
        ))}
      </div>

      {mode === 'upload' && (
        <div
          onDragOver={e => { e.preventDefault(); setDragging(true); }}
          onDragLeave={() => setDragging(false)}
          onDrop={handleDrop}
          onClick={() => fileRef.current.click()}
          style={{
            border: `2px dashed ${dragging ? 'var(--accent)' : file ? 'var(--green)' : 'var(--border-mid)'}`,
            borderRadius: 'var(--radius-lg)', padding: '44px 24px', textAlign: 'center',
            cursor: 'pointer', transition: 'all 0.2s',
            background: dragging ? 'var(--bg3)' : file ? 'var(--green-bg)' : 'var(--bg3)',
            marginBottom: 16,
          }}
        >
          <input ref={fileRef} type="file" accept=".csv" style={{ display: 'none' }} onChange={e => handleFile(e.target.files[0])} />
          <div style={{ fontSize: 28, marginBottom: 10 }}>{file ? '📄' : '☁'}</div>
          {file ? (
            <>
              <div className="mono" style={{ fontSize: 13, color: 'var(--green)', fontWeight: 500, marginBottom: 3 }}>{file.name}</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{(file.size / 1024).toFixed(1)} KB · click to change</div>
            </>
          ) : (
            <>
              <div style={{ fontFamily: 'Syne', fontSize: 14, fontWeight: 600, marginBottom: 5 }}>Drop your CSV here</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>or click to browse · one email per row · first column</div>
            </>
          )}
        </div>
      )}

      {mode === 'paste' && (
        <div style={{ marginBottom: 16 }}>
          <textarea
            placeholder={`Paste emails here — one per line or comma-separated:\n\njohn@acme.com\nsales@company.com\ncontact@brand.io`}
            value={pasteText}
            onChange={e => setPasteText(e.target.value)}
          />
          {emailCount > 0 && (
            <div style={{ marginTop: 8, fontSize: 12, color: 'var(--green)', fontFamily: 'DM Mono' }}>
              ✓ {emailCount.toLocaleString()} email{emailCount !== 1 ? 's' : ''} detected
            </div>
          )}
        </div>
      )}

      {error && (
        <div style={{ marginBottom: 14, background: 'var(--red-bg)', border: '1.5px solid var(--red-border)', borderRadius: 'var(--radius)', padding: '10px 14px', color: 'var(--red)', fontSize: 13 }}>
          {error}
        </div>
      )}

      <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
        <button className="btn-primary" onClick={handleStart} disabled={!canStart || uploading}>
          {uploading ? <><span className="spinner" style={{ marginRight: 6 }}>↻</span>Starting...</> : 'Start verification →'}
        </button>
        {(file || pasteText) && <button className="btn-ghost" onClick={reset}>Clear</button>}
      </div>

      <div style={{ marginTop: 20, display: 'flex', gap: 18, fontSize: 12, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>
        <span>30 threads</span><span>·</span><span>~2k–8k emails/hr</span><span>·</span><span>SMTP + MX + catch-all</span>
      </div>
    </div>
  );
}
